using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;
namespace CircuitoStudio {
 public sealed class AmbInspection {
  internal byte[] Original;public DxfInspection Drawing=new DxfInspection();public int RecordCount;public Dictionary<string,int> Classes=new Dictionary<string,int>();public List<string> Warnings=new List<string>();
  public string Summary{get{return "AMB AMOEBA 1.1; "+RecordCount+" registros estruturais; "+Drawing.Entities.Count+" primitivas ativas na prévia.\r\n"+String.Join("; ",Classes.Select(x=>x.Key+"="+x.Value).ToArray())+"\r\n"+String.Join("\r\n",Warnings.ToArray())+"\r\nReexportação preserva todos os bytes do arquivo lido, incluindo blocos, atributos e dados não interpretados. Não edita AMB, converte para DXF ou recupera circuitos e cálculos. Assinatura e estrutura não autenticam o arquivo; checksum proprietário não verificado.";}}
  public void SaveOriginal(string path){DrawingDxf.Atomic(path,Original);}
 }
 // Empirical AMOEBA 1.1 structure verified against native SDK drawings and the official prototype.
 // Byte-preserving inspection only; metadata and proprietary checksum are not interpreted.
 public static class DrawingAmb {
  const int MaxBytes=32*1024*1024;static readonly Encoding Ansi=Encoding.GetEncoding(1252,EncoderFallback.ExceptionFallback,DecoderFallback.ExceptionFallback);
  static int I(byte[] b,int p){if(p<0||p>b.Length-4)throw new InvalidDataException("AMB truncado.");return BitConverter.ToInt32(b,p);}
  static double D(byte[] b,int p){if(p<0||p>b.Length-8)throw new InvalidDataException("AMB truncado.");double v=BitConverter.ToDouble(b,p);if(Double.IsNaN(v)||Double.IsInfinity(v)||Math.Abs(v)>1e9)throw new InvalidDataException("Coordenada AMB inválida ou fora de ±1e9.");return v;}
  static bool Is(byte[] b,int p,string text){byte[] s=Encoding.ASCII.GetBytes(text);if(p<0||p>b.Length-s.Length)return false;for(int i=0;i<s.Length;i++)if(b[p+i]!=s[i])return false;return true;}
  public static AmbInspection Inspect(string path){var f=new FileInfo(path);if(!f.Exists||f.Length>MaxBytes||f.Length<68)throw new InvalidDataException("AMB ausente, truncado ou excede 32 MiB.");return Inspect(File.ReadAllBytes(path));}
  public static AmbInspection Inspect(byte[] input){if(input==null||input.Length<68||input.Length>MaxBytes)throw new InvalidDataException("AMB ausente, truncado ou excede 32 MiB.");byte[] b=(byte[])input.Clone();if(!Is(b,0,"AMOEBA DATA FILE, ver 1.1")||b[25]!=0)throw new InvalidDataException("Formato AMB não suportado; esperado AMOEBA 1.1 (não JPCAD ELEMS).");int n=I(b,36),count=I(b,52);if(I(b,32)!=68||I(b,40)!=101||n<0||n>4096||count<0||count>500000||I(b,56)!=count||I(b,60)!=count)throw new InvalidDataException("Cabeçalho AMB fora do formato verificado.");int pos=68;var names=new List<string>();for(int i=0;i<n;i++){if(pos>b.Length-101)throw new InvalidDataException("Tabela de classes AMB truncada.");int end=Array.IndexOf(b,(byte)0,pos,101);if(end<pos||end==pos)throw new InvalidDataException("Nome de classe AMB inválido.");string name=Encoding.ASCII.GetString(b,pos,end-pos);if(!name.StartsWith("AMOEBA/ENTITIES/",StringComparison.Ordinal))throw new InvalidDataException("Classe AMB fora do formato verificado.");names.Add(name.Substring(16));pos+=101;}
   var result=new AmbInspection{Original=b,RecordCount=count};result.Drawing.Original=b;result.Drawing.Version="AMB 1.1";bool complex=false;
   for(int i=0;i<count;i++){if(pos>b.Length-9)throw new InvalidDataException("Registro AMB truncado.");int tag=b[pos],size=I(b,pos+1),raw=I(b,pos+5),type=raw&65535;if(tag<0||tag>2||size<8||size>b.Length-pos-1||type>=names.Count)throw new InvalidDataException("Registro AMB fora do formato verificado.");string name=names[type];if(!result.Classes.ContainsKey(name))result.Classes[name]=0;result.Classes[name]++;int stop=pos+1+size,p=pos+9;
    if(tag==0){var e=new DxfEntity{Type=name,Layer="(camada AMB não resolvida)"};bool known=(raw>>16)==0;if(name=="LINE"&&size==60&&known){e.X=D(b,p);e.Y=D(b,p+8);e.X2=D(b,p+16);e.Y2=D(b,p+24);result.Drawing.Entities.Add(e);}else if(name=="CIRCLE"&&size==52&&known){e.X=D(b,p);e.Y=D(b,p+8);e.Radius=D(b,p+16);if(e.Radius<=0)throw new InvalidDataException("Raio AMB inválido.");result.Drawing.Entities.Add(e);}else if(name=="TEXT"&&size>=86&&known&&b[p+44]==0){e.X=D(b,p);e.Y=D(b,p+8);e.Height=D(b,p+16);e.Rotation=D(b,p+24)*180/Math.PI;int textStart=p+77;int zero=Array.IndexOf(b,(byte)0,textStart,stop-textStart);if(e.Height<=0||zero!=stop-1)throw new InvalidDataException("Texto AMB fora do formato verificado.");e.Text=Ansi.GetString(b,textStart,zero-textStart);result.Drawing.Entities.Add(e);}else{complex=true;if(!result.Drawing.Unsupported.ContainsKey(name))result.Drawing.Unsupported[name]=0;result.Drawing.Unsupported[name]++;}}
    if(tag==1){complex=true;if(!result.Drawing.Unsupported.ContainsKey("registro tag1"))result.Drawing.Unsupported["registro tag1"]=0;result.Drawing.Unsupported["registro tag1"]++;}
    pos=stop;
   }
   if(!Is(b,pos,"AMOEBA_VARS_DCB")||b.Length-pos<128)throw new InvalidDataException("Seção final AMB ausente ou truncada.");string tail=Encoding.ASCII.GetString(b,pos,b.Length-pos);if(!tail.Contains("AMOEBA_DISPLAY_DCB")||!tail.Contains("AMOEBA_PRINT_SETTINGS_DCB"))throw new InvalidDataException("Seções finais AMB não reconhecidas.");result.Warnings.Add("Prévia limitada a LINE/CIRCLE/TEXT ativos simples (texto alinhado pela base inferior esquerda); não reproduz fontes, cores, espessuras, escala de impressão ou visibilidade por camada.");if(complex)result.Warnings.Add("PRÉVIA INCOMPLETA: há entidades ativas não interpretadas, inclusive possíveis inserções de blocos. Nenhum conteúdo é eliminado na reexportação.");return result;
  }
 }
}
